    const ASSETS = {"calm":"data:image/webp;base64,","serious":"data:image/webp;base64,","thinking":"data:image/webp;base64,","sorry":"data:image/webp;base64,"};

    //#region redact.mjs
    // src/redact.mjs — 零依赖脱敏。所有对外输出（fixtures / miss 日志 / UI 原文）都过这一层。
    const RULES = [
      { id: 'bearer', re: /\bBearer\s+[A-Za-z0-9._\-+/=]{8,}/g, to: 'Bearer [REDACTED]' },
      { id: 'sk', re: /\bsk-[A-Za-z0-9._\-]{8,}/g, to: 'sk-[REDACTED]' },
      { id: 'apikey', re: /\b(api[_-]?key|apiKey|token|access[_-]?token)\s*[:=]\s*["']?[A-Za-z0-9._\-+/=]{6,}["']?/gi, to: '$1=[REDACTED]' },
      { id: 'maskedkey', re: /\*{3,}[A-Za-z0-9]{3,}/g, to: '****[REDACTED]' },
      { id: 'requestid', re: /\b(request[_-]?id|retryId|callId|toolCallId|session-\w+)\s*[:=]\s*["']?[A-Za-z0-9._\-]{6,}["']?/gi, to: '$1=[ID]' },
      { id: 'uuid', re: /\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b/gi, to: '[UUID]' },
      { id: 'winpath-quoted', re: /"[A-Za-z]:\\(?:[^"\\]+\\)*[^"\\]+"/g, to: '"[PATH]"' },
      { id: 'winpath', re: /[A-Za-z]:\\(?:[^\\\s"']+\\)*[^\\\s"']+/g, to: '[PATH]' },
      { id: 'unixpath', re: /(?<![\w])\/(?:home|Users|tmp|var|etc)\/[^\s"']+/g, to: '[PATH]' },
      { id: 'phone', re: /(?<!\d)1[3-9]\d{9}(?!\d)/g, to: '[PHONE]' },
      { id: 'ipv4', re: /(?<![\d.])(?:\d{1,3}\.){3}\d{1,3}(?![\d.])/g, to: '[IP]' },
    ];
    
    /** @returns {{ text: string, redacted: boolean, hits: string[] }} */
    function redact(input) {
      const raw = typeof input === 'string' ? input : String(input ?? '');
      let text = raw;
      const hits = [];
      for (const rule of RULES) {
        rule.re.lastIndex = 0;
        const next = text.replace(rule.re, rule.to);
        if (next !== text) { hits.push(rule.id); text = next; }
        rule.re.lastIndex = 0;
      }
      return { text, redacted: hits.length > 0, hits };
    }
    
    function hashMessage(input) {
      // FNV-1a 32bit，仅用于本地 miss 日志去重，非安全用途
      const s = typeof input === 'string' ? input : String(input ?? '');
      let h = 0x811c9dc5;
      for (let i = 0; i < s.length; i++) {
        h ^= s.charCodeAt(i);
        h = Math.imul(h, 0x01000193) >>> 0;
      }
      return h.toString(16).padStart(8, '0');
    }
    //#endregion
    
    //#region match.mjs
    // src/match.mjs — 匹配顺序固定：codeExact → codePattern（码族）→ 命名捕获组正则 → UNKNOWN。
    // 零依赖、零 I/O。正则只作降级路径，码比文案稳定。
    //
    // codePattern 是 2026-11-05 新增的第 1.5 层：官方码表里有大量同一子系统的码
    // （TEAM_* / GOAL_* / ASK_* / SESSION_* …），一个码族一条词条即可全覆盖，
    // 不必为每个码手写。码族词条只给「属于哪个子系统 + 原文里有具体原因」这种
    // 不编造的说法，绝不猜具体成因。
    
    const MAX_PATTERN = 512;
    const NESTED_QUANTIFIER = /\([^)]*[+*][^)]*\)[+*{]/;
    
    function normalizeMessage(message) {
      return String(message ?? '').replace(/\s+/g, ' ').trim();
    }
    
    function isSafePattern(pattern) {
      if (typeof pattern !== 'string' || pattern.length === 0) return true;
      if (pattern.length > MAX_PATTERN) return false;
      if (NESTED_QUANTIFIER.test(pattern)) return false;
      try { new RegExp(pattern); return true; } catch { return false; }
    }
    
    function compile(entry) {
      const p = entry?.match?.pattern;
      if (!p || !isSafePattern(p)) return null;
      try { return new RegExp(p); } catch { return null; }
    }
    
    function codeMatches(entry, code) {
      const spec = entry?.match?.codeExact;
      if (!spec || !code) return false;
      return spec.split('|').some((c) => c.trim() === code);
    }
    
    /** 码族匹配：match.codePattern 是一段正则，作用于 code 本身（作者自己写锚点）。 */
    function codeFamilyMatches(entry, code) {
      const p = entry?.match?.codePattern;
      if (!p || !code || !isSafePattern(p)) return false;
      try { return new RegExp(p).test(code); } catch { return false; }
    }
    
    /**
     * @param {{code?:string,message:string,status?:number,provider?:string}} input
     * @param {{entries:Array,fallback:object}} dict
     * @returns {{entry:object, matchedBy:'code'|'code-family'|'pattern'|'fallback', slots:object, safe:boolean}}
     */
    function matchEntry(input, dict) {
      const code = typeof input?.code === 'string' ? input.code : undefined;
      const msg = normalizeMessage(input?.message);
      const entries = Array.isArray(dict?.entries) ? dict.entries : [];
      const fallback = dict?.fallback ?? { id: 'UNKNOWN', title: '未收录的报错', summary: '原因未验证', causeAssertion: 'forbidden' };
    
      // 1) 结构化码优先
      const byCode = entries
        .filter((e) => codeMatches(e, code))
        .sort((a, b) => (b.match?.priority ?? 0) - (a.match?.priority ?? 0));
      if (byCode.length) {
        return { entry: byCode[0], matchedBy: 'code', slots: extractSlots(byCode[0], msg), safe: true };
      }
    
      // 1.5) 码族（TEAM_* / GOAL_* / …），只在没有精确词条时兜这一层
      if (code) {
        const byFamily = entries
          .filter((e) => codeFamilyMatches(e, code))
          .sort((a, b) => (b.match?.priority ?? 0) - (a.match?.priority ?? 0));
        if (byFamily.length) {
          return { entry: byFamily[0], matchedBy: 'code-family', slots: { code }, safe: true };
        }
      }
    
      // 2) 模板正则降级（按 priority 降序）
      const byPattern = [];
      for (const e of entries) {
        const re = compile(e);
        if (!re) continue;
        const m = re.exec(msg);
        if (!m) continue;
        byPattern.push({ e, score: e.match?.priority ?? 0, groups: m.groups ?? {} });
      }
      byPattern.sort((a, b) => b.score - a.score);
      if (byPattern.length) {
        return { entry: byPattern[0].e, matchedBy: 'pattern', slots: byPattern[0].groups, safe: true };
      }
    
      // 3) 兜底
      return { entry: fallback, matchedBy: 'fallback', slots: {}, safe: true };
    }
    
    function extractSlots(entry, msg) {
      const slots = {};
      for (const name of entry?.match?.slots ?? []) {
        const re = compile(entry);
        const m = re?.exec(msg);
        if (m?.groups?.[name] !== undefined) slots[name] = m.groups[name];
      }
      return slots;
    }
    
    /** 词典加载期校验：返回问题列表，空数组表示通过。 */
    function lintDictionary(dict) {
      const problems = [];
      const seen = new Set();
      for (const e of dict?.entries ?? []) {
        if (!e.id) problems.push(`entry missing id`);
        else if (seen.has(e.id)) problems.push(`duplicate id: ${e.id}`);
        else seen.add(e.id);
        if (!Array.isArray(e.evidence) || e.evidence.length === 0) problems.push(`${e.id}: evidence 为空`);
        if (!isSafePattern(e.match?.pattern)) problems.push(`${e.id}: pattern 不安全或过长`);
        if (e.match?.codePattern !== undefined && !isSafePattern(e.match.codePattern)) problems.push(`${e.id}: codePattern 不安全或过长`);
        if (e.match?.codePattern !== undefined && e.match?.codeExact !== undefined) problems.push(`${e.id}: codeExact 与 codePattern 只能二选一`);
        for (const c of e.causes ?? []) {
          if (!['确定', '可能', '需查'].includes(c.certainty)) problems.push(`${e.id}: 非法 certainty ${c.certainty}`);
          if (c.certainty === '确定' && !c.evidenceRef) problems.push(`${e.id}: 确定级 cause 缺 evidenceRef`);
        }
        for (const a of e.actions ?? []) {
          if (!['点按钮', '改配置', '换模型', '新建会话', '看日志'].includes(a.op)) problems.push(`${e.id}: 非法 op ${a.op}`);
        }
        // 文案闸门：summary 禁含因果连词
        if (/\b(因为|由于|导致|所以|原因是|因由)\b/.test(e.summary ?? '')) problems.push(`${e.id}: summary 含因果连词`);
      }
      return problems;
    }
    //#endregion
    
    //#region resolve.mjs
    // src/resolve.mjs — 纯函数引擎主入口。零 I/O、零模型调用、零网络、零 DSH 依赖、fail-open。
    
    
    const OPS = new Set(['点按钮', '改配置', '换模型', '新建会话', '看日志']);
    
    /** 用户自定义词条合并：字段级覆盖，causeAssertion 单向锁定（禁止提升）。 */
    function mergeUserEntries(entries, userEntries) {
      const map = new Map(entries.map((e) => [e.id, { ...e }]));
      for (const u of userEntries ?? []) {
        if (!u || !u.id) continue;
        if (u.disabled === true) { map.delete(u.id); continue; }
        const base = map.get(u.id);
        const merged = base ? { ...base, ...u } : { ...u };
        if (base) {
          const rank = { forbidden: 0, conditional: 1, allowed: 2 };
          if (rank[merged.causeAssertion] > rank[base.causeAssertion]) merged.causeAssertion = base.causeAssertion;
          merged.evidence = base.evidence;
          merged.version = base.version;
          merged.origin = 'custom';
        }
        map.set(u.id, merged);
      }
      return [...map.values()];
    }
    
    /**
     * @param {{code?:string,message:string,status?:number,provider?:string,event?:object}} input
     * @param {{sessionTokens?:number,modelContextWindow?:number,toolOutputBytes?:number,imageCount?:number,compactionOutcome?:string}} context
     * @param {{entries:Array,fallback:object,version?:string}} dict
     */
    function resolveError(input, context = {}, dict = { entries: [], fallback: {} }) {
      try {
        const rawMessage = String(input?.message ?? '');
        const cleaned = redact(rawMessage);
        const { entry, matchedBy, slots } = matchEntry({ ...input, message: cleaned.text }, dict);
    
        const assertion = entry.causeAssertion ?? 'forbidden';
        const causes = (entry.causes ?? []).map((c) => ({ ...c, resolved: resolveCertainty(c, assertion, context) }));
    
        return {
          id: entry.id ?? 'UNKNOWN',
          title: entry.title ?? '未收录的报错',
          summary: entry.summary ?? '原因未验证',
          causes,
          impact: entry.impact ?? '',
          actions: (entry.actions ?? []).filter((a) => OPS.has(a.op)),
          severity: entry.severity ?? 'warning',
          retryable: Boolean(entry.retryable),
          autoRecoverable: Boolean(entry.autoRecoverable),
          causeAssertion: assertion,
          showRawMessage: Boolean(entry.showRawMessage) || matchedBy === 'fallback',
          raw: { message: cleaned.text, code: input?.code ?? '', redacted: cleaned.redacted, redactHits: cleaned.hits },
          slots,
          impactSlots: slots,
          provenance: {
            dictVersion: dict.version ?? entry.version ?? '0.1.0',
            matchedBy,
            evidence: entry.evidence ?? [],
            docRefs: entry.docRefs ?? [],
            logRefs: entry.logRefs ?? [],
            templateId: entry.templateId ?? '',
          },
          chain: undefined,
          _entry: entry,
        };
      } catch (err) {
        // fail-open：任何异常都降级为 UNKNOWN，不阻断 UI
        return {
          id: 'UNKNOWN', title: '未收录的报错', summary: '注解引擎降级，原文已保留。',
          causes: [{ text: '引擎异常', certainty: '需查', resolved: '原因未验证' }],
          impact: '', actions: [{ text: '复制报错原文', op: '点按钮' }],
          severity: 'warning', retryable: false, autoRecoverable: false,
          causeAssertion: 'forbidden', showRawMessage: true,
          raw: { message: String(input?.message ?? ''), code: input?.code ?? '', redacted: false, redactHits: [] },
          slots: {}, impactSlots: {},
          provenance: { dictVersion: '0.1.0', matchedBy: 'fallback', evidence: [], docRefs: [], logRefs: [], error: String(err) },
          chain: undefined, _entry: dict?.fallback ?? {},
        };
      }
    }
    
    function resolveCertainty(cause, assertion, context) {
      if (assertion === 'forbidden' || cause.certainty === '需查') return '原因未验证';
      if (cause.certainty === '确定') return '确定';
      // 「可能」仅在 requiresContext 全部取到时保持「可能」，否则也标未验证
      const req = cause.requiresContext ?? [];
      if (req.length === 0) return '可能';
      const available = req.every((k) => context?.[k] !== undefined && context?.[k] !== null);
      return available ? '可能（已取到依据）' : '需查看依据';
    }
    
    /** 短注解：≤40 字，不含原因。 */
    function renderShort(ann, t) {
      const first = ann.actions[0]?.text ?? '查看原文';
      let s = t('gloss.short', { title: ann.title, summary: ann.summary }) + ' · ' + t('gloss.suggest', { action: first });
      if (ann.causeAssertion === 'forbidden') s += t('gloss.unknown.hint');
      return s.trim();
    }
    
    /** 展开详情：按 certainty 分档渲染原因，forbidden 时整段替换。 */
    function renderDetail(ann, t) {
      const lines = [];
      lines.push(`${t('gloss.raw')}：${ann.raw.message}`);
      lines.push(`${t('gloss.gloss')}：${ann.summary}`);
      const basisLabel = ann.causeAssertion === 'allowed'
        ? t('gloss.basis.local')
        : ann.causeAssertion === 'conditional'
          ? t('gloss.basis.session')
          : t('gloss.basis.unverified');
      lines.push(`${t('gloss.cause')}（${basisLabel}）：`);
      if (ann.causeAssertion === 'forbidden') {
        lines.push(`  ${t('gloss.causeForbidden')}`);
      } else {
        for (const c of ann.causes) {
          const req = (c.requiresContext ?? []).join(', ');
          const logs = ann.provenance.logRefs.join(', ') || '~/.dsh/sessions/';
          if (c.certainty === '确定') lines.push(`  ${t('gloss.causeConfirmed', { text: c.text })}`);
          else if (c.certainty === '可能') lines.push(`  ${t('gloss.causeLikely', { text: c.text, requires: req || '会话上下文' })}`);
          else lines.push(`  ${t('gloss.causeNeeds', { text: c.text, logs })}`);
        }
      }
      lines.push(`${t('gloss.impact')}：${ann.impact}`);
      lines.push(`${t('gloss.actions')}：`);
      ann.actions.forEach((a, i) => lines.push(`  ${i + 1}. [${a.op}] ${a.text}`));
      if (ann.provenance.logRefs.length) lines.push(`${t('gloss.logs')}：${ann.provenance.logRefs.join(' · ')}`);
      const ev = ann.provenance.evidence[0];
      if (ev) lines.push(`${t('gloss.provenance')}：${ev.path}${ev.line ? ':' + ev.line : ''} · 词典 ${ann.id} v${ann.provenance.dictVersion}`);
      return lines.join('\n');
    }
    
    /** 简单模板函数：{key} 占位替换。 */
    function makeT(dict, locale = 'zh-CN') {
      return (key, vars = {}) => {
        const template = dict?.[locale]?.[key] ?? dict?.['zh-CN']?.[key] ?? key;
        return String(template).replace(/\{(\w+)\}/g, (_, k) => (vars[k] !== undefined ? String(vars[k]) : `{${k}}`));
      };
    }
    //#endregion
    
    //#region chain.mjs
    // src/chain.mjs — v0.3 因果链聚合（A 阶段先实现，供自测与后续 Host 订阅复用）。
    
    /**
     * 把一串 session 事件聚成因果链。识别「溢出 → 自动压缩 → 压缩失败 → 本轮终止」这条典型链。
     * @param {Array<{type:string,seq:number,time:number,data:object}>} events
     */
    function aggregateChain(events = []) {
      const rows = [...events].sort((a, b) => (a.seq ?? 0) - (b.seq ?? 0));
      const steps = [];
      for (const e of rows) {
        const d = e.data ?? {};
        if (e.type === 'turn/end' && d.reason?.kind === 'error') {
          const err = d.reason.error ?? {};
          steps.push({ step: '本轮失败', code: err.code ?? '', message: normalizeMessage(err.message), at: e.seq, kind: 'terminal' });
        } else if (e.type === 'llm/retry' && d.failure?.code) {
          steps.push({ step: '模型重试', code: d.failure.code, message: normalizeMessage(d.failure.message), at: e.seq, kind: 'retry' });
        } else if (e.type === 'tool/result' && d.error?.code) {
          steps.push({ step: '工具报错', code: d.error.code, message: normalizeMessage(d.message?.content?.[0]?.text), at: e.seq, kind: 'tool' });
        } else if (e.type === 'compaction/summary' || e.type === 'manual-compaction') {
          const text = normalizeMessage(d.outcome?.text ?? d.text ?? '');
          if (text) steps.push({ step: '压缩结算', code: 'COMPACTION', message: text, at: e.seq, kind: 'compaction' });
        }
      }
      const hasOverflow = steps.some((s) => s.code === 'CONTEXT_WINDOW_EXCEEDED');
      const compactionFailed = steps.some((s) => /could not produce a useful summary/i.test(s.message));
      const rootCause = hasOverflow
        ? (compactionFailed
            ? '上下文溢出后自动压缩未产出可用摘要，溢出未被回收，本轮终止。'
            : '上下文溢出触发本轮失败，自动压缩结果需查看会话日志。')
        : '';
      return {
        steps,
        rootCause,
        isChain: hasOverflow && compactionFailed,
        suggestedActions: hasOverflow
          ? ['新建会话并保留关键结论', '手动执行 /compact', '查看会话 token 曲线与压缩记录']
          : [],
      };
    }
    //#endregion

    // client/client.js — DSH 适配层入口。只用公开扩展点：locale.register / slots.inject / slots.register。
    //
    // 挂载点（2026-11-05 依 `dsh-cordis-client-runner` 内的官方 slot 契约目录核对后改正）：
    //   1) conversation.chat.turnTail  —— kind: list / scope: session  ⇒ 一个轮次可挂多个条目，
    //      官方 ui-deliverables / ui-plan / ui-schedule 都占这个座位。
    //      ownerProps = { turn, seq, openFile }，standardProps 里带 useChat 选择器。
    //   2) settings.section            —— kind: list / scope: root，设置页的存在证明。
    //
    // ⚠️ 曾经写错的两处（本文件已改）：
    //   · 原挂在 conversation.chat.node 上、key 自造 'error-gloss'。该 slot 是 **keyed**，
    //     key 域被固定为 ChatNodeKind（assistant-step / turn-error / tool-call / …），
    //     自造 key 永远不会被 dispatch，等于装了什么都不显示；改用已存在的 key 则会
    //     顶掉官方渲染器（契约标 replaceRisk: shadows-shipped-ui）。故放弃该座位。
    //   · 报错气泡本身由 ui-chat 的 TurnErrorNodeView 渲染，插件只能**另起兄弟行**，
