          let ann;
          try {
            ann = resolveError({ code: input.code, message: input.message }, {}, GLOSS_DATA);
          } catch { continue; }
          if (ann.id === 'UNKNOWN') { misses += 1; continue; }
          hits.push({
            key: `${key}`,
            seq: node.seq ?? node.data?.seq,
            code: input.code,
            message: input.message,
            id: ann.id,
          });
